"use client"
import * as React from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import type { LegacyColumnDef as ColumnDef } from '@tanstack/react-table/legacy'
import type { SortingState } from '@tanstack/react-table'
import type { TodoListItem } from '../types'
import extensionPoints from '../extension-points'
import { DataTable, type DataTableExportFormat } from '@open-mercato/ui/backend/DataTable'
import type { PreparedExport } from '@open-mercato/shared/lib/crud/exporters'
import { RowActions } from '@open-mercato/ui/backend/RowActions'
import type { FilterValues } from '@open-mercato/ui/backend/FilterBar'
import { BooleanIcon, EnumBadge, useSeverityPreset } from '@open-mercato/ui/backend/ValueIcons'
import { Button } from '@open-mercato/ui/primitives/button'
import { fetchCrudList, buildCrudExportUrl, deleteCrud } from '@open-mercato/ui/backend/utils/crud'
import { readApiResultOrThrow, withScopedApiRequestHeaders } from '@open-mercato/ui/backend/utils/apiCall'
import { buildOptimisticLockHeader } from '@open-mercato/ui/backend/utils/optimisticLock'
import { surfaceRecordConflict } from '@open-mercato/ui/backend/conflicts'
import { useCustomFieldDefs, type CustomFieldDefDto } from '@open-mercato/ui/backend/utils/customFieldDefs'
import { applyCustomFieldVisibility } from '@open-mercato/ui/backend/utils/customFieldColumns'
import { flash } from '@open-mercato/ui/backend/FlashMessages'
import { useOrganizationScopeVersion } from '@open-mercato/shared/lib/frontend/useOrganizationScope'
import { useT } from '@«redacted:high-entropy»'
import { useConfirmDialog } from '@open-mercato/ui/backend/confirm-dialog'
import Link from 'next/link'
import { useRouter } from 'next/navigation'

type TodoRow = TodoListItem & { organization_name?: string }

type TodosResponse = {
  items: TodoListItem[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

type OrganizationsResponse = {
  items: Array<{ id: string; name: string }>
}

const EMPTY_CUSTOM_FIELD_DEFS: CustomFieldDefDto[] = []

function buildBaseColumns(t: (key: string, params?: Record<string, string | number>) => string, severityPreset: ReturnType<typeof useSeverityPreset>): ColumnDef<TodoRow>[] {
  return [
    { accessorKey: 'title', header: t('example.todos.table.column.title'), meta: { priority: 1 } },
    { accessorKey: 'organization_name', header: t('example.todos.table.column.organization'), enableSorting: false, meta: { priority: 3 } },
    {
      accessorKey: 'is_done',
      header: t('example.todos.table.column.done'),
      meta: { priority: 2 },
      cell: ({ getValue }) => <BooleanIcon value={!!getValue()} />,
    },
    { accessorKey: 'cf_priority', header: t('example.todos.table.column.priority'), meta: { priority: 4 } },
    {
      accessorKey: 'cf_severity',
      header: t('example.todos.table.column.severity'),
      cell: ({ getValue }) => {
        const raw = getValue()
        return <EnumBadge value={typeof raw === 'string' ? raw : null} map={severityPreset} />
      },
      meta: { priority: 5 },
    },
    {
      accessorKey: 'cf_blocked',
      header: t('example.todos.table.column.blocked'),
      meta: { priority: 6 },
      cell: ({ getValue }) => <BooleanIcon value={!!getValue()} />,
    },
    {
      accessorKey: 'cf_labels',
      header: t('example.todos.table.column.labels'),
      cell: ({ getValue }) => {
        const raw = getValue()
        const vals = Array.isArray(raw) ? raw.map((value) => String(value)) : []
        if (vals.length === 0) return <span className="text-xs text-muted-foreground">—</span>
        return (
          <span className="flex flex-wrap gap-1">
            {vals.map((v) => (
              <span key={v} className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border bg-accent/50">
                {v}
              </span>
            ))}
          </span>
        )
      },
      meta: { priority: 4 },
    },
  ]
}

export default function TodosTable() {
  const t = useT()
  const router = useRouter()
  const queryClient = useQueryClient()
  const { confirm, ConfirmDialogElement } = useConfirmDialog()
  const severityPreset = useSeverityPreset()
  const [title, setTitle] = React.useState('')
  const [values, setValues] = React.useState<FilterValues>({})
  const [sorting, setSorting] = React.useState<SortingState>([{ id: 'title', desc: false }])
  const [page, setPage] = React.useState(1)
  const scopeVersion = useOrganizationScopeVersion()

  const queryParams = React.useMemo(() => {
    const params = new URLSearchParams({
      page: page.toString(),
      pageSize: '50',
      sortField: sorting[0]?.id || 'title',
      sortDir: sorting[0]?.desc ? 'desc' : 'asc',
    })

    if (title) params.set('title', title)

    Object.entries(values).forEach(([k, v]) => {
      if (k === 'created_at' && v && typeof v === 'object') {
        const range = v as { from?: string; to?: string }
        if (range.from) params.set('createdFrom', range.from)
        if (range.to) params.set('createdTo', range.to)
        return
      }
      if (k === 'is_done') {
        if (v === true || v === false) params.set('isDone', String(v))
        return
      }
      if (k.startsWith('cf_')) {
        if (Array.isArray(v)) params.set(k, v.map((value) => String(value)).join(','))
        else if (v != null && v !== '') params.set(k, String(v))
      }
    })

    return params.toString()
  }, [page, sorting, title, values])

  const { data: rawCfDefs } = useCustomFieldDefs('example:todo', {
    keyExtras: [scopeVersion],
  })
  const cfDefs = rawCfDefs ?? EMPTY_CUSTOM_FIELD_DEFS

  const [columns, setColumns] = React.useState<ColumnDef<TodoRow>[]>([])

  const computedColumns = React.useMemo(() => {
    const base = buildBaseColumns(t, severityPreset)
    if (!cfDefs.length) return base
    return applyCustomFieldVisibility(base, cfDefs)
  }, [cfDefs, t])

  React.useEffect(() => {
    setColumns(computedColumns)
  }, [computedColumns])

  const viewExportColumns = React.useMemo(() => {
    const sourceColumns = columns.length ? columns : computedColumns
    return sourceColumns
      .map((col) => {
        const accessorKey = (col as any).accessorKey
        if (!accessorKey || typeof accessorKey !== 'string') return null
        if ((col as any).meta?.hidden) return null
        const header = typeof col.header === 'string'
          ? col.header
          : accessorKey.startsWith('cf_')
            ? accessorKey.slice(3)
            : accessorKey
        return { field: accessorKey, header }
      })
      .filter((col): col is { field: string; header: string } => !!col)
  }, [columns, computedColumns])

  const fullExportParams = React.useMemo(() => {
    const params: Record<string, string> = { exportScope: 'full', all: 'true' }
    const sort = sorting[0]
    if (sort?.id) {
      params.sortField = sort.id
      params.sortDir = sort.desc ? 'desc' : 'asc'
    }
    return params
  }, [sorting])

  const effectiveColumns = columns.length ? columns : computedColumns

  const { data: todosData, isLoading, error } = useQuery<TodosResponse>({
    queryKey: ['todos', queryParams, scopeVersion],
    queryFn: async () => fetchCrudList<TodoListItem>('example/todos', Object.fromEntries(new URLSearchParams(queryParams))),
  })

  const organizationIds = React.useMemo(() => {
    if (!todosData?.items) return []
    const ids = todosData.items
      .map((todo) => todo.organization_id)
      .filter((id): id is string => id != null)
    return [...new Set(ids)]
  }, [todosData?.items])

  const { data: orgsData } = useQuery<OrganizationsResponse>({
    queryKey: ['organizations', organizationIds],
    queryFn: async () => {
      if (organizationIds.length === 0) return { items: [] }
      return readApiResultOrThrow<OrganizationsResponse>(
        `/api/example/organizations?ids=${organizationIds.join(',')}`,
        undefined,
        { errorMessage: t('example.todos.table.error.generic', 'Failed to fetch organizations') },
      )
    },
    enabled: organizationIds.length > 0,
  })

  const orgMap = React.useMemo(() => {
    if (!orgsData?.items) return {}
    return orgsData.items.reduce((acc, org) => {
      acc[org.id] = org.name
      return acc
    }, {} as Record<string, string>)
  }, [orgsData?.items])

  const todosWithOrgNames = React.useMemo(() => {
    if (!todosData?.items) return []
    return todosData.items.map((todo) => ({
      ...todo,
      organization_name: todo.organization_id
        ? orgMap[todo.organization_id] || t('example.todos.table.organization.unknown')
        : t('example.todos.table.organization.none'),
    }))
  }, [orgMap, t, todosData?.items])

  const exportConfig = React.useMemo(() => ({
    view: {
      description: t('example.todos.table.export.view'),
      prepare: async (): Promise<{ prepared: PreparedExport; filename: string }> => {
        const rows = todosWithOrgNames.map((row) => {
          const out: Record<string, unknown> = {}
          for (const col of viewExportColumns) {
            out[col.field] = (row as Record<string, unknown>)[col.field]
          }
          return out
        })
        const prepared: PreparedExport = {
          columns: viewExportColumns.map((col) => ({ field: col.field, header: col.header })),
          rows,
        }
        return { prepared, filename: 'todos_view' }
      },
    },
    full: {
      description: t('example.todos.table.export.full'),
      getUrl: (format: DataTableExportFormat) =>
        buildCrudExportUrl('example/todos', fullExportParams, format),
      filename: () => 'todos_full',
    },
  }), [fullExportParams, viewExportColumns, t, todosWithOrgNames])

  const handleSortingChange = (newSorting: SortingState) => {
    setSorting(newSorting)
    setPage(1)
  }

  const handleReset = () => {
    setTitle('')
    setValues({})
    setPage(1)
  }

  if (error) {
    return <div className="text-sm text-destructive">{t('example.todos.table.error.generic')}</div>
  }

  return (
    <>
      <DataTable
        title={t('example.todos.table.title')}
        actions={(
          <Button asChild>
            <Link href="/backend/todos/create">{t('example.todos.table.actions.create')}</Link>
          </Button>
        )}
        columns={effectiveColumns}
        data={todosWithOrgNames}
        exporter={exportConfig}
        searchValue={title}
        onSearchChange={(v) => {
          setTitle(v)
          setPage(1)
        }}
        searchAlign="right"
        filters={[
          { id: 'is_done', label: t('example.todos.table.filters.done'), type: 'checkbox' },
          { id: 'created_at', label: t('example.todos.table.filters.createdAt'), type: 'dateRange' },
        ]}
        filterValues={values}
        onFiltersApply={(vals: FilterValues) => {
          setValues(vals)
          setPage(1)
        }}
        onFiltersClear={() => handleReset()}
        entityId="example:todo"
        sortable
        sorting={sorting}
        onSortingChange={handleSortingChange}
        perspective={{ tableId: extensionPoints.hosts.todosTable.tableId }}
        rowActions={(row) => (
          <RowActions
            items={[
              { label: t('example.todos.table.actions.edit'), href: `/backend/todos/${row.id}/edit` },
              {
                label: t('example.todos.table.actions.delete'),
                destructive: true,
                onSelect: async () => {
                  const confirmed = await confirm({
                    title: t('example.todos.table.confirm.delete'),
                    variant: 'destructive',
                  })
                  if (!confirmed) return
                  try {
                    // Row deletes carry the row's own optimistic-lock version, so a
                    // list rendered before someone else edited the record fails with
                    // a 409 instead of deleting a row the user never saw.
                    await withScopedApiRequestHeaders(
                      buildOptimisticLockHeader(row.updatedAt),
                      () => deleteCrud('example/todos', row.id),
                    )
                    flash(t('example.todos.form.flash.deleted'), 'success')
                    queryClient.invalidateQueries({ queryKey: ['todos'] })
                  } catch (err) {
                    if (surfaceRecordConflict(err, t)) {
                      queryClient.invalidateQueries({ queryKey: ['todos'] })
                      return
                    }
                    const message =
                      err instanceof Error && err.message
                        ? err.message
                        : t('example.todos.table.error.delete')
                    flash(message, 'error')
                  }
                },
              },
            ]}
          />
        )}
        pagination={{
          page,
          pageSize: 50,
          total: todosData?.total || 0,
          totalPages: todosData?.totalPages || 0,
          onPageChange: setPage,
        }}
        isLoading={isLoading}
        onRowClick={(row) => router.push(`/backend/todos/${row.id}/edit`)}
      />
      {ConfirmDialogElement}
    </>
  )
}

"use client"
import * as React from 'react'
import { CrudForm, type CrudField, type CrudFormGroup } from '@open-mercato/ui/backend/CrudForm'
import { ErrorMessage, RecordNotFoundState } from '@open-mercato/ui/backend/detail'
import { createCrud, fetchCrudList, updateCrud, deleteCrud } from '@open-mercato/ui/backend/utils/crud'
import { withFlash } from '@open-mercato/ui/backend/utils/flash'
import { SendObjectMessageDialog } from '@open-mercato/ui/backend/messages'
import { useT } from '@«redacted:high-entropy»'
import { extractCustomFieldEntries } from '@open-mercato/shared/lib/crud/custom-fields-client'
import type { TodoListItem } from '../types'
import extensionPoints from '../extension-points'

// Derived from the declared host rather than duplicated: `hasDeclarationBinding`
// (packages/cli/src/lib/generators/module-extension-facts.ts) only treats a host as
// BOUND when its declared source file references `extensionPoints.hosts.<key>`, and
// `CrudForm` normalizes the colon form back to the host's dotted `entityId`.
const ENTITY_ID = extensionPoints.hosts.todoForm.entityId.replace('.', ':')
const LIST_HREF = '/backend/todos'

type Translate = ReturnType<typeof useT>

type TodoCustomFieldValues = Record<`cf_${string}`, unknown>

export type TodoFormValues = {
  id: string
  title: string
  notes: string
  is_done: boolean
  // Carries the optimistic-lock version into `CrudForm`, which auto-derives the
  // expected-version header from `initialValues.updatedAt` for update AND delete.
  updatedAt?: string | null
} & TodoCustomFieldValues

function useTodoFields(t: Translate): CrudField[] {
  return React.useMemo<CrudField[]>(() => [
    {
      id: 'title',
      label: t('example.todos.form.fields.title.label'),
      type: 'text',
      required: true,
      placeholder: t('example.todos.form.fields.title.placeholder'),
    },
    {
      id: 'notes',
      label: t('example.todos.form.fields.notes.label'),
      type: 'textarea',
      description: t('example.todos.form.fields.notes.description'),
      placeholder: t('example.todos.form.fields.notes.placeholder'),
    },
    { id: 'is_done', label: t('example.todos.form.fields.isDone.label'), type: 'checkbox' },
    { id: 'cf_blocked', label: t('example.todos.table.column.blocked'), type: 'checkbox' },
  ], [t])
}

function useTodoGroups(t: Translate, extraGroup: CrudFormGroup): CrudFormGroup[] {
  return React.useMemo<CrudFormGroup[]>(() => [
    { id: 'details', title: t('example.todos.form.groups.details'), column: 1, fields: ['title', 'notes'] },
    { id: 'status', title: t('example.todos.form.groups.status'), column: 2, fields: ['is_done', 'cf_blocked'] },
    { id: 'attributes', title: t('example.todos.form.groups.attributes'), column: 1, kind: 'customFields' },
    extraGroup,
  ], [t, extraGroup])
}

/**
 * Maps a loaded Todo into the form's initial values.
 *
 * Exported as a pure function so the optimistic-lock wiring is testable: `CrudForm`
 * auto-derives the expected-version header from `initialValues.updatedAt`, so dropping
 * `updatedAt` here silently disables optimistic locking for update AND delete while every
 * other assertion in the module still passes. `todo-form-values.test.ts` pins it.
 */
export function toTodoFormValues(item: TodoListItem): TodoFormValues {
  const extended = item as TodoListItem & Record<string, unknown>
  const cfInit = extractCustomFieldEntries(extended) as Partial<TodoCustomFieldValues>
  return {
    id: item.id,
    title: item.title,
    // `notes` is encrypted at rest and only projected on single-record reads. The
    // edit form loads exactly that way (`fetchCrudList(..., { ids, pageSize: 1 })`),
    // so a null here means "empty", not "not selected".
    notes: item.notes ?? '',
    is_done: Boolean(item.is_done),
    updatedAt: item.updatedAt ?? null,
    ...(cfInit as TodoCustomFieldValues),
    cf_priority: extended.cf_priority ?? cfInit.cf_priority,
    cf_severity: extended.cf_severity ?? cfInit.cf_severity,
    cf_blocked: extended.cf_blocked ?? cfInit.cf_blocked,
    cf_labels: extended.cf_labels ?? cfInit.cf_labels,
    cf_assignee: extended.cf_assignee ?? cfInit.cf_assignee,
    cf_description: extended.cf_description ?? cfInit.cf_description,
  }
}

export function TodoCreateForm() {
  const t = useT()
  const fields = useTodoFields(t)
  const tipsGroup = React.useMemo<CrudFormGroup>(() => ({
    id: 'tips',
    title: t('example.todos.form.groups.tips'),
    column: 2,
    component: () => (
      <div className="text-sm text-muted-foreground">
        {t('example.todos.form.groups.tips.body')}
      </div>
    ),
  }), [t])
  const groups = useTodoGroups(t, tipsGroup)
  const successRedirect = React.useMemo(
    () => `${LIST_HREF}?flash=${encodeURIComponent(t('example.todos.form.flash.created'))}&type=success`,
    [t],
  )

  return (
    <CrudForm
      title={t('example.todos.form.create.title')}
      backHref={LIST_HREF}
      entityId={ENTITY_ID}
      fields={fields}
      groups={groups}
      submitLabel={t('example.todos.form.create.submit')}
      cancelHref={LIST_HREF}
      successRedirect={successRedirect}
      onSubmit={async (vals) => { await createCrud('example/todos', vals) }}
    />
  )
}

export function TodoEditForm({ id }: { id: string }) {
  const t = useT()
  const [initial, setInitial] = React.useState<TodoFormValues | null>(null)
  const [loading, setLoading] = React.useState(true)
  const [err, setErr] = React.useState<string | null>(null)
  const [isNotFound, setIsNotFound] = React.useState(false)
  const fields = useTodoFields(t)
  const actionsGroup = React.useMemo<CrudFormGroup>(() => ({
    id: 'actions',
    title: t('example.todos.form.groups.actions'),
    column: 2,
    component: ({ setValue }) => (
      <div className="flex items-center gap-2">
        <button
          type="button"
          className="h-8 rounded border px-2 text-sm"
          onClick={() => setValue('is_done', true)}
        >
          {t('example.todos.form.groups.actions.markDone')}
        </button>
        <button
          type="button"
          className="h-8 rounded border px-2 text-sm"
          onClick={() => setValue('is_done', false)}
        >
          {t('example.todos.form.groups.actions.markTodo')}
        </button>
      </div>
    ),
  }), [t])
  const groups = useTodoGroups(t, actionsGroup)
  const successRedirect = React.useMemo(
    () => `${LIST_HREF}?flash=${encodeURIComponent(t('example.todos.form.flash.saved'))}&type=success`,
    [t],
  )
  const deleteRedirect = React.useMemo(
    () => withFlash(LIST_HREF, t('example.todos.form.flash.deleted'), 'success'),
    [t],
  )

  React.useEffect(() => {
    let cancelled = false
    async function load() {
      setLoading(true)
      setErr(null)
      setIsNotFound(false)
      try {
        const data = await fetchCrudList<TodoListItem>('example/todos', { ids: String(id), pageSize: 1 })
        const item = data?.items?.[0]
        if (!item) {
          if (!cancelled) setIsNotFound(true)
          return
        }
        if (!cancelled) setInitial(toTodoFormValues(item))
      } catch (error: unknown) {
        if (!cancelled) {
          if ((error as { status?: number }).status === 404) {
            setIsNotFound(true)
          } else {
            const message = error instanceof Error && error.message ? error.message : t('example.todos.form.error.load')
            setErr(message)
          }
        }
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [id, t])

  const fallbackInitialValues = React.useMemo<TodoFormValues>(() => ({
    id,
    title: '',
    notes: '',
    is_done: false,
    updatedAt: null,
  }), [id])

  if (isNotFound) {
    return (
      <RecordNotFoundState
        label={t('example.todos.form.error.notFound')}
        backHref={LIST_HREF}
        backLabel={t('example.todos.form.actions.backToList', 'Back to todos')}
      />
    )
  }

  if (err) return <ErrorMessage label={err} />

  return (
    <CrudForm<TodoFormValues>
      title={t('example.todos.form.edit.title')}
      backHref={LIST_HREF}
      extraActions={(
        <SendObjectMessageDialog
          object={{
            entityModule: 'example',
            entityType: 'todo',
            entityId: id,
            previewData: {
              title: (initial?.title && initial.title.trim().length > 0) ? initial.title : fallbackInitialValues.title,
              metadata: {
                [t('example.todos.form.fields.isDone.label')]: (initial?.is_done ?? false)
                  ? t('common.yes', 'Yes')
                  : t('common.no', 'No'),
              },
            },
          }}
          viewHref={`${LIST_HREF}/${id}/edit`}
        />
      )}
      entityId={ENTITY_ID}
      fields={fields}
      groups={groups}
      initialValues={initial ?? fallbackInitialValues}
      submitLabel={t('example.todos.form.edit.submit')}
      cancelHref={LIST_HREF}
      successRedirect={successRedirect}
      deleteRedirect={deleteRedirect}
      isLoading={loading}
      loadingMessage={t('example.todos.form.loading')}
      onSubmit={async (vals) => { await updateCrud('example/todos', vals) }}
      onDelete={async () => { await deleteCrud('example/todos', String(id)) }}
    />
  )
}

