"use client"
import * as React from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import type { LegacyColumnDef as ColumnDef } from '@tanstack/react-table/legacy'
import type { SortingState } from '@tanstack/react-table'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { DataTable } from '@open-mercato/ui/backend/DataTable'
import { RowActions } from '@open-mercato/ui/backend/RowActions'
import { Button } from '@open-mercato/ui/primitives/button'
import { fetchCrudList, deleteCrud } from '@open-mercato/ui/backend/utils/crud'
import { withScopedApiRequestHeaders, readApiResultOrThrow } from '@open-mercato/ui/backend/utils/apiCall'
import { buildOptimisticLockHeader } from '@open-mercato/ui/backend/utils/optimisticLock'
import { surfaceRecordConflict } from '@open-mercato/ui/backend/conflicts'
import { flash } from '@open-mercato/ui/backend/FlashMessages'
import { useConfirmDialog } from '@open-mercato/ui/backend/confirm-dialog'
import { useOrganizationScopeVersion } from '@open-mercato/shared/lib/frontend/useOrganizationScope'
import { useT } from '@«redacted:high-entropy»'
import type { BookListItem } from '../types'

const LIST_PATH = '/backend/library/books'
const CRUD_RESOURCE = 'library/books'

type BooksResponse = {
  items: BookListItem[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

function buildColumns(t: (key: string, params?: Record<string, string | number>) => string): ColumnDef<BookListItem>[] {
  return [
    { accessorKey: 'title', header: t('library.books.table.column.title'), meta: { priority: 1 } },
    { accessorKey: 'author', header: t('library.books.table.column.author'), meta: { priority: 2 } },
    {
      accessorKey: 'isbn',
      header: t('library.books.table.column.isbn'),
      cell: ({ getValue }) => {
        const value = getValue()
        return value ? <span className="font-mono text-xs">{String(value)}</span> : <span className="text-muted-foreground">—</span>
      },
      meta: { priority: 4 },
    },
    { accessorKey: 'totalCopies', header: t('library.books.table.column.copies'), meta: { priority: 3 } },
    {
      accessorKey: 'availableCopies',
      header: t('library.books.table.column.available'),
      cell: ({ row, getValue }) => {
        const available = Number(getValue() ?? 0)
        const total = Number(row.original.totalCopies ?? 0)
        const tone = available <= 0 ? 'text-destructive' : available < total ? 'text-amber-600 dark:text-amber-500' : 'text-emerald-600 dark:text-emerald-500'
        return <span className={tone}>{available}</span>
      },
      meta: { priority: 5 },
    },
  ]
}

export default function BooksTable() {
  const t = useT()
  const router = useRouter()
  const queryClient = useQueryClient()
  const { confirm, ConfirmDialogElement } = useConfirmDialog()
  const scopeVersion = useOrganizationScopeVersion()
  const [search, setSearch] = React.useState('')
  const [sorting, setSorting] = React.useState<SortingState>([{ id: 'title', desc: false }])
  const [page, setPage] = React.useState(1)

  const queryParams = React.useMemo(() => {
    const params = new URLSearchParams({
      page: page.toString(),
      pageSize: '50',
      sortField: sorting[0]?.id || 'title',
      sortDir: sorting[0]?.desc ? 'desc' : 'asc',
    })
    if (search) params.set('search', search)
    return params.toString()
  }, [page, sorting, search])

  const { data, isLoading, error } = useQuery<BooksResponse>({
    queryKey: ['library/books', queryParams, scopeVersion],
    queryFn: async () =>
      readApiResultOrThrow<BooksResponse>(
        `/api/library/books?${queryParams}`,
        undefined,
        { errorMessage: t('library.books.table.error.generic') },
      ),
  })

  const columns = React.useMemo(() => buildColumns(t), [t])

  if (error) {
    return <div className="text-sm text-destructive">{t('library.books.table.error.generic')}</div>
  }

  return (
    <>
      <DataTable
        title={t('library.books.table.title')}
        actions={
          <Button asChild>
            <Link href={`${LIST_PATH}/create`}>{t('library.books.table.actions.create')}</Link>
          </Button>
        }
        columns={columns}
        data={data?.items ?? []}
        searchValue={search}
        onSearchChange={(value) => {
          setSearch(value)
          setPage(1)
        }}
        searchPlaceholder={t('library.books.table.searchPlaceholder')}
        emptyStateMessage={t('library.books.table.empty')}
        sortable
        sorting={sorting}
        onSortingChange={(next) => {
          setSorting(next)
          setPage(1)
        }}
        rowActions={(row) => (
          <RowActions
            items={[
              { label: t('library.books.table.actions.edit'), href: `${LIST_PATH}/${row.id}/edit` },
              {
                label: t('library.books.table.actions.delete'),
                destructive: true,
                onSelect: async () => {
                  const confirmed = await confirm({
                    title: t('library.books.table.confirm.delete'),
                    variant: 'destructive',
                  })
                  if (!confirmed) return
                  try {
                    await withScopedApiRequestHeaders(
                      buildOptimisticLockHeader(row.updatedAt),
                      () => deleteCrud(CRUD_RESOURCE, row.id),
                    )
                    flash(t('library.books.form.flash.deleted'), 'success')
                    queryClient.invalidateQueries({ queryKey: ['library/books'] })
                  } catch (err) {
                    if (surfaceRecordConflict(err, t)) {
                      queryClient.invalidateQueries({ queryKey: ['library/books'] })
                      return
                    }
                    const message = err instanceof Error && err.message ? err.message : t('library.books.table.error.delete')
                    flash(message, 'error')
                  }
                },
              },
            ]}
          />
        )}
        pagination={{
          page,
          pageSize: 50,
          total: data?.total ?? 0,
          totalPages: data?.totalPages ?? 0,
          onPageChange: setPage,
        }}
        isLoading={isLoading}
        onRowClick={(row) => router.push(`${LIST_PATH}/${row.id}/edit`)}
      />
      {ConfirmDialogElement}
    </>
  )
}

"use client"
import * as React from 'react'
import { CrudForm, type CrudField, type CrudFormGroup } from '@open-mercato/ui/backend/CrudForm'
import { ErrorMessage, RecordNotFoundState } from '@open-mercato/ui/backend/detail'
import { createCrud, fetchCrudList, updateCrud, deleteCrud } from '@open-mercato/ui/backend/utils/crud'
import { withFlash } from '@open-mercato/ui/backend/utils/flash'
import { useT } from '@«redacted:high-entropy»'
import type { BookListItem } from '../types'
import extensionPoints from '../extension-points'

// CrudForm normalizes the colon form `library:book` to the `library.book` spot id.
const ENTITY_ID = extensionPoints.hosts.bookForm.entityId
const LIST_HREF = '/backend/library/books'

type Translate = ReturnType<typeof useT>

export type BookFormValues = {
  id: string
  title: string
  author: string
  isbn: string
  publisher: string
  publishedYear: number | string
  description: string
  totalCopies: number | string
  // Optimistic-lock version; CrudForm auto-derives the expected-version header
  // from `initialValues.updatedAt` for update AND delete.
  updatedAt?: string | null
}

export function toBookFormValues(item: BookListItem): BookFormValues {
  return {
    id: item.id,
    title: item.title,
    author: item.author,
    isbn: item.isbn ?? '',
    publisher: item.publisher ?? '',
    publishedYear: item.publishedYear ?? '',
    description: item.description ?? '',
    totalCopies: item.totalCopies,
    updatedAt: item.updatedAt ?? null,
  }
}

function useBookFields(t: Translate): CrudField[] {
  return React.useMemo<CrudField[]>(() => [
    {
      id: 'title',
      label: t('library.books.form.fields.title.label'),
      type: 'text',
      required: true,
      placeholder: t('library.books.form.fields.title.placeholder'),
    },
    {
      id: 'author',
      label: t('library.books.form.fields.author.label'),
      type: 'text',
      required: true,
      placeholder: t('library.books.form.fields.author.placeholder'),
    },
    {
      id: 'isbn',
      label: t('library.books.form.fields.isbn.label'),
      type: 'text',
      description: t('library.books.form.fields.isbn.description'),
      placeholder: t('library.books.form.fields.isbn.placeholder'),
    },
    { id: 'publisher', label: t('library.books.form.fields.publisher.label'), type: 'text' },
    { id: 'publishedYear', label: t('library.books.form.fields.publishedYear.label'), type: 'number' },
    { id: 'totalCopies', label: t('library.books.form.fields.totalCopies.label'), type: 'number', required: true, description: t('library.books.form.fields.totalCopies.description') },
    { id: 'description', label: t('library.books.form.fields.description.label'), type: 'textarea' },
  ], [t])
}

function useBookGroups(t: Translate): CrudFormGroup[] {
  return React.useMemo<CrudFormGroup[]>(() => [
    { id: 'details', title: t('library.books.form.groups.details'), column: 1, fields: ['title', 'author', 'description'] },
    { id: 'inventory', title: t('library.books.form.groups.inventory'), column: 2, fields: ['isbn', 'publisher', 'publishedYear', 'totalCopies'] },
  ], [t])
}

export function BookCreateForm() {
  const t = useT()
  const fields = useBookFields(t)
  const groups = useBookGroups(t)
  const successRedirect = React.useMemo(
    () => `${LIST_HREF}?flash=${encodeURIComponent(t('library.books.form.flash.created'))}&type=success`,
    [t],
  )

  return (
    <CrudForm<BookFormValues>
      title={t('library.books.create.title')}
      backHref={LIST_HREF}
      entityId={ENTITY_ID}
      fields={fields}
      groups={groups}
      submitLabel={t('library.books.form.create.submit')}
      cancelHref={LIST_HREF}
      successRedirect={successRedirect}
      onSubmit={async (vals) => { await createCrud('library/books', vals) }}
    />
  )
}

export function BookEditForm({ id }: { id: string }) {
  const t = useT()
  const [initial, setInitial] = React.useState<BookFormValues | null>(null)
  const [loading, setLoading] = React.useState(true)
  const [err, setErr] = React.useState<string | null>(null)
  const [isNotFound, setIsNotFound] = React.useState(false)
  const fields = useBookFields(t)
  const groups = useBookGroups(t)
  const successRedirect = React.useMemo(
    () => `${LIST_HREF}?flash=${encodeURIComponent(t('library.books.form.flash.saved'))}&type=success`,
    [t],
  )
  const deleteRedirect = React.useMemo(
    () => withFlash(LIST_HREF, t('library.books.form.flash.deleted'), 'success'),
    [t],
  )

  React.useEffect(() => {
    let cancelled = false
    async function load() {
      setLoading(true)
      setErr(null)
      setIsNotFound(false)
      try {
        const data = await fetchCrudList<BookListItem>('library/books', { ids: String(id), pageSize: 1 })
        const item = data?.items?.[0]
        if (!item) {
          if (!cancelled) setIsNotFound(true)
          return
        }
        if (!cancelled) setInitial(toBookFormValues(item))
      } catch (error: unknown) {
        if (!cancelled) {
          if ((error as { status?: number }).status === 404) {
            setIsNotFound(true)
          } else {
            const message = error instanceof Error && error.message ? error.message : t('library.books.form.error.load')
            setErr(message)
          }
        }
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [id, t])

  const fallbackInitialValues = React.useMemo<BookFormValues>(() => ({
    id,
    title: '',
    author: '',
    isbn: '',
    publisher: '',
    publishedYear: '',
    description: '',
    totalCopies: 1,
    updatedAt: null,
  }), [id])

  if (isNotFound) {
    return (
      <RecordNotFoundState
        label={t('library.books.form.error.notFound')}
        backHref={LIST_HREF}
        backLabel={t('library.books.form.actions.backToList')}
      />
    )
  }

  if (err) return <ErrorMessage label={err} />

  return (
    <CrudForm<BookFormValues>
      title={t('library.books.edit.title')}
      backHref={LIST_HREF}
      entityId={ENTITY_ID}
      fields={fields}
      groups={groups}
      initialValues={initial ?? fallbackInitialValues}
      submitLabel={t('library.books.form.edit.submit')}
      cancelHref={LIST_HREF}
      successRedirect={successRedirect}
      deleteRedirect={deleteRedirect}
      isLoading={loading}
      loadingMessage={t('library.books.form.loading')}
      onSubmit={async (vals) => { await updateCrud('library/books', vals) }}
      onDelete={async () => { await deleteCrud('library/books', String(id)) }}
    />
  )
}

